CREATE TABLE IF NOT EXISTS "OWNER" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100) NOT NULL,
	"address_district" VARCHAR(100) NOT NULL, -- เพิ่มเพื่อทำรายงานรายเขตตามโจทย์
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "OWNER_PHONE" (
	"owner_id" INTEGER NOT NULL,
	"phone" VARCHAR(20) NOT NULL,
	PRIMARY KEY("owner_id", "phone") -- กำหนด Composite Primary Key
);

CREATE TABLE IF NOT EXISTS "PET" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100) NOT NULL,
	"birth_date" DATE NOT NULL,
	"owner_id" INTEGER NOT NULL, -- สัตว์ทุกตัวต้องมีเจ้าของ
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "VET" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100) NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "VET_SPECIALTY" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"specialty_name" VARCHAR(100) NOT NULL,
	"vet_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "VISIT" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"visit_no" INTEGER NOT NULL CHECK ("visit_no" > 0),
	"visit_date" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
	"total_amount" NUMERIC(10,2) NOT NULL DEFAULT 0.00 CHECK ("total_amount" >= 0),
	"pet_id" INTEGER NOT NULL,
	"vet_id" INTEGER NOT NULL, -- ต้องระบุสัตวแพทย์เสมอ
	PRIMARY KEY("id"),
	CONSTRAINT "uq_pet_visit" UNIQUE("pet_id", "visit_no") -- คุมลำดับการเข้าตรวจ 1, 2, 3... ของสัตว์แต่ละตัว
);

CREATE TABLE IF NOT EXISTS "SERVICE_ITEM" (
	"id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
	"item_name" VARCHAR(100) NOT NULL,
	"dosage" VARCHAR(50), -- ขนาดยา
	"days" INTEGER CHECK ("days" > 0), -- จำนวนวัน
	"quantity" INTEGER NOT NULL DEFAULT 1 CHECK ("quantity" > 0),
	"price" NUMERIC(10,2) NOT NULL CHECK ("price" >= 0),
	"visit_id" INTEGER NOT NULL,
	PRIMARY KEY("id")
);

-- ==========================================
-- Foreign Key Constraints ที่ถูกต้อง
-- ==========================================

-- OWNER_PHONE -> OWNER
ALTER TABLE "OWNER_PHONE"
ADD FOREIGN KEY ("owner_id") REFERENCES "OWNER"("id") ON DELETE CASCADE;

-- PET -> OWNER
ALTER TABLE "PET"
ADD FOREIGN KEY ("owner_id") REFERENCES "OWNER"("id") ON DELETE RESTRICT;

-- VET_SPECIALTY -> VET
ALTER TABLE "VET_SPECIALTY"
ADD FOREIGN KEY ("vet_id") REFERENCES "VET"("id") ON DELETE CASCADE;

-- VISIT -> PET & VET
ALTER TABLE "VISIT"
ADD FOREIGN KEY ("pet_id") REFERENCES "PET"("id") ON DELETE RESTRICT;

ALTER TABLE "VISIT"
ADD FOREIGN KEY ("vet_id") REFERENCES "VET"("id") ON DELETE RESTRICT;

-- SERVICE_ITEM -> VISIT
ALTER TABLE "SERVICE_ITEM"
ADD FOREIGN KEY ("visit_id") REFERENCES "VISIT"("id") ON DELETE CASCADE;
